const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Define geometry and parameters
    const centerPoint = ee.Geometry.Point([7.578886, 38.602260]);
    const region = centerPoint.buffer(30000); // 30 km radius
    const minLakeArea = 25e6; // 25 km² in square meters

    // 2. Load JRC Global Surface Water dataset
    const gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater');

    // Check if data exists
    const occurrence = gsw.select('occurrence');
    const testCount = occurrence.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 3000,
      maxPixels: 1e9
    }).get('occurrence');

    const pixelCount = await testCount.getInfo();

    if (pixelCount === 0 || pixelCount === null) {
      console.log('No surface water data available for region.');
      console.log('<answer>C1</answer>');
      return;
    }

    console.log(`Total pixels in region: ${pixelCount}`);

    // 3. Identify permanent water bodies (occurrence > 75%)
    const waterMask = occurrence.gt(75);

    // Count valid water pixels
    const waterPixelCount = await waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 3000,
      maxPixels: 1e9
    }).get('occurrence').getInfo();

    if (waterPixelCount === 0 || waterPixelCount === null) {
      console.log('No permanent water pixels found.');
      console.log('<answer>B</answer>');
      return;
    }

    console.log(`Water pixels found: ${waterPixelCount}`);

    // 4. Identify connected water bodies using connectedPixelCount
    const waterBodies = waterMask.selfMask();
    const connected = waterBodies.connectedPixelCount({
      maxSize: 10000,
      eightConnected: false
    });

    // Calculate area of each connected component (pixel count * 900 m² for 30m resolution)
    const pixelArea = ee.Image.pixelArea();
    const waterArea = connected.multiply(pixelArea).divide(1e6); // Convert to km²

    // 5. Mask to only keep lakes larger than 25 km²
    const largeLakes = waterArea.updateMask(waterArea.gte(25));

    // Count distinct large lakes using reduceToVectors
    const vectors = largeLakes.reduceToVectors({
      geometry: region,
      scale: 3000,
      geometryType: 'polygon',
      maxPixels: 1e9,
      bestEffort: true
    });

    const lakeCount = await vectors.size().getInfo();

    if (lakeCount === null || lakeCount === undefined) {
      console.log('Calculation failed.');
      console.log('<answer>C3</answer>');
      return;
    }

    console.log(`Number of lakes > 25 km²: ${lakeCount}`);

    // 6. Final answer
    if (lakeCount > 2) {
      console.log('<answer>A</answer>');
    } else {
      console.log('<answer>B</answer>');
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log('<answer>D</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
